199  struct GlyphVarData
   200  {
   201    const TupleVarHeader &get_tuple_var_header (void) const
   202    { return StructAfter<TupleVarHeader> (data); }
   203
   204    struct tuple_iterator_t
   205    {
   206      void init (const GlyphVarData *var_data_, unsigned int length_, unsigned int axis_count_)
   207      {
   208        var_data = var_data_;
   209        length = length_;
   210        index = 0;
   211        axis_count = axis_count_;
   212        current_tuple = &var_data->get_tuple_var_header ();
   213        data_offset = 0;
   214      }
   215
   216      bool get_shared_indices (hb_vector_t<unsigned int> &shared_indices /* OUT */)
   217      {
   218        if (var_data->has_shared_point_numbers ())
   219        {
   220          hb_bytes_t bytes ((const char *) var_data, length);
   221          const HBUINT8 *base = &(var_data+var_data->data);
   222          const HBUINT8 *p = base;
   223          if (!unpack_points (p, shared_indices, bytes)) return false;
   224          data_offset = p - base;
   225        }
   226        return true;
   227      }
   228
   229      bool is_valid () const
   230      {
   231        return (index < var_data->tupleVarCount.get_count ()) &&
   232               in_range (current_tuple) &&
   233               current_tuple->get_size (axis_count);
   234      }
   235
   236      bool move_to_next ()
   237      {
   238        data_offset += current_tuple->get_data_size ();
   239        current_tuple = &current_tuple->get_next (axis_count);
   240        index++;
   241        return is_valid ();
   242      }
   243
   244      bool in_range (const void *p, unsigned int l) const
   245      { return (const char*) p >= (const char*) var_data && (const char*) p+l <= (const char*) var_data + length; }
   246
   247      template <typename T> bool in_range (const T *p) const { return in_range (p, sizeof (*p)); }
   248
   249      const HBUINT8 *get_serialized_data () const
   250      { return &(var_data+var_data->data) + data_offset; }
   251
   252      private:
   253      const GlyphVarData *var_data;
   254      unsigned int length;
   255      unsigned int index;
   256      unsigned int axis_count;
   257      unsigned int data_offset;
   258
   259      public:
   260      const TupleVarHeader *current_tuple;
